import React, { useEffect, useState, useRef } from 'react';
import { transactionEntryAPI } from '../../services/api';
import TransactionDetailsModal from './TransactionDetailsModal';
import './Styles/TransactionView.css';

const TransactionView = ({ onTabChange }) => {
  const [buyTransactions, setBuyTransactions] = useState([]);
  const [sellTransactions, setSellTransactions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('all'); // 'all', 'buy', 'sell'
  const [selectedCompany, setSelectedCompany] = useState('');
  const [companies, setCompanies] = useState([]);
  const [selectedTransaction, setSelectedTransaction] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  
  // Ref for the scrollable table container
  const tableWrapperRef = useRef(null);

  const fetchTransactions = async () => {
    setLoading(true);
    try {
      // Get all buy transactions from the new transaction entries API
      const buyData = await transactionEntryAPI.getAllBuyTransactions();
      // Get all sell transactions
      const sellData = await transactionEntryAPI.getAllSellTransactions();
      setBuyTransactions(buyData);
      setSellTransactions(sellData);
      
      // Extract unique companies from all transactions
      const allTransactions = [...buyData, ...sellData];
      const uniqueCompanies = [...new Set(allTransactions.map(tx => 
        tx.company_name || tx.companyName
      ).filter(Boolean))].sort();
      setCompanies(uniqueCompanies);
    } catch (err) {
      console.error('Error fetching transactions:', err);
      setBuyTransactions([]);
      setSellTransactions([]);
      setCompanies([]);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchTransactions();
  }, []);

  // Combine and sort all transactions by date
  const allTransactions = [
    ...buyTransactions.map(tx => ({ ...tx, type: 'BUY' })),
    ...sellTransactions.map(tx => ({ ...tx, type: 'SELL' }))
  ].sort((a, b) => new Date(b.trade_date || b.created_at) - new Date(a.trade_date || a.created_at));

  // Filter transactions by tab and company
  const filteredTransactions = (() => {
    let transactions = activeTab === 'all' 
      ? allTransactions 
      : activeTab === 'buy' 
      ? buyTransactions.map(tx => ({ ...tx, type: 'BUY' }))
      : sellTransactions.map(tx => ({ ...tx, type: 'SELL' }));
    
    // Apply company filter if selected
    if (selectedCompany) {
      transactions = transactions.filter(tx => 
        (tx.company_name || tx.companyName) === selectedCompany
      );
    }
    
    return transactions;
  })();


  const formatCurrency = (value) => {
    return parseFloat(value || 0).toLocaleString(undefined, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });
  };

  const formatDate = (dateString) => {
    if (!dateString) return '-';
    return new Date(dateString).toLocaleDateString();
  };

  const calculatePricePerShare = (transaction) => {
    const netValue = parseFloat(transaction.net_value || transaction.netValue || 0);
    const quantity = parseFloat(transaction.quantity || 0);
    
    if (quantity === 0) return 0;
    return netValue / quantity;
  };

  const handleRowClick = (transaction) => {
    setSelectedTransaction(transaction);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setSelectedTransaction(null);
  };

  const handleSave = async () => {
    // Refresh the transactions list
    await fetchTransactions();
  };

  return (
    <div className="transaction-view-container">
      <div className="transaction-view-header">
        <h2 className="transaction-view-title">All Transactions</h2>
        <div className="transaction-header-controls">
          <div className="company-filter-container">
            <label htmlFor="company-filter" className="company-filter-label">
              Filter by Company:
            </label>
            <select
              id="company-filter"
              value={selectedCompany}
              onChange={(e) => setSelectedCompany(e.target.value)}
              className="company-filter-dropdown"
              disabled={loading}
            >
              <option value="">All Companies</option>
              {companies.map(company => (
                <option key={company} value={company}>
                  {company}
                </option>
              ))}
            </select>
          </div>
          <button 
            onClick={fetchTransactions} 
            className="transaction-refresh-btn"
            disabled={loading}
          >
            <svg className="refresh-icon" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M4 2a1 1 0 011 1v2.101a7.002 7.002 0 0111.601 2.566 1 1 0 11-1.885.666A5.002 5.002 0 005.999 7H9a1 1 0 010 2H4a1 1 0 01-1-1V3a1 1 0 011-1zm.008 9.057a1 1 0 011.276.61A5.002 5.002 0 0014.001 13H11a1 1 0 110-2h5a1 1 0 011 1v5a1 1 0 11-2 0v-2.101a7.002 7.002 0 01-11.601-2.566 1 1 0 01.61-1.276z" clipRule="evenodd"/>
            </svg>
            {loading ? 'Loading...' : 'Refresh'}
          </button>
        </div>
      </div>

      {/* Tab Navigation */}
      <div className="transaction-tabs">
        <button 
          className={`transaction-tab ${activeTab === 'all' ? 'active' : ''}`}
          onClick={() => setActiveTab('all')}
        >
          All Transactions ({filteredTransactions.length})
        </button>
        <button 
          className={`transaction-tab ${activeTab === 'buy' ? 'active' : ''}`}
          onClick={() => setActiveTab('buy')}
        >
          Buy Transactions ({buyTransactions.filter(tx => 
            !selectedCompany || (tx.company_name || tx.companyName) === selectedCompany
          ).length})
        </button>
        <button 
          className={`transaction-tab ${activeTab === 'sell' ? 'active' : ''}`}
          onClick={() => setActiveTab('sell')}
        >
          Sell Transactions ({sellTransactions.filter(tx => 
            !selectedCompany || (tx.company_name || tx.companyName) === selectedCompany
          ).length})
        </button>
      </div>


      {/* Transactions Table */}
      <div className="transaction-table-container">
        {loading ? (
          <div className="transaction-loading">Loading transactions...</div>
        ) : filteredTransactions.length === 0 ? (
          <div className="transaction-empty">No transactions found.</div>
        ) : (
          <div 
            ref={tableWrapperRef}
            className="transaction-table-wrapper"
          >
            <table className="transaction-table">
              <thead className="transaction-table-head">
                <tr>
                  <th>Type</th>
                  <th>Company</th>
                  <th>Portfolio</th>
                  <th>Deal Number</th>
                  <th>Quantity</th>
                  <th>Price</th>
                  <th>Gross Value</th>
                  <th>Net Value</th>
                  <th>Avg Price/Share</th>
                  <th>Trade Date</th>
                  <th>Settlement Date</th>
                  <th>Broker</th>
                  <th>Contract #</th>
                  {activeTab !== 'sell' && <th>Money Gen Cost (Daily)</th>}
                  {activeTab !== 'buy' && <th>Capital Gain</th>}
                </tr>
              </thead>
              <tbody className="transaction-table-body">
                {filteredTransactions.map((transaction, index) => (
                  <tr 
                    key={`${transaction.type}-${transaction.id}`} 
                    className={`transaction-row ${transaction.type.toLowerCase()}-row`}
                    onClick={() => handleRowClick(transaction)}
                    style={{ cursor: 'pointer' }}
                  >
                    <td className="transaction-type-cell">
                      <span className={`transaction-type-badge ${transaction.type.toLowerCase()}`}>
                        {transaction.type}
                      </span>
                    </td>
                    <td className="transaction-company-cell">
                      {transaction.company_name || transaction.companyName || '-'}
                    </td>
                    <td className="transaction-portfolio-cell">
                      {transaction.portfolio || transaction.portfolio_name || transaction.portfolioName || '-'}
                    </td>
                    <td className="transaction-deal-cell">
                      {transaction.deal_number || transaction.contract_number || transaction.contractNumber || '-'}
                    </td>
                    <td className="transaction-quantity-cell">
                      {formatCurrency(transaction.quantity)}
                    </td>
                    <td className="transaction-price-cell">
                      {formatCurrency(
                        transaction.type === 'SELL' 
                          ? (transaction.sold_price || transaction.soldPrice || transaction.price || 0)
                          : (transaction.price || transaction.boughtPrice || 0)
                      )}
                    </td>
                    <td className="transaction-gross-cell">
                      {formatCurrency(transaction.gross_value || transaction.grossValue)}
                    </td>
                    <td className="transaction-net-cell">
                      {formatCurrency(transaction.net_value || transaction.netValue)}
                    </td>
                    <td className="transaction-avg-price-cell">
                      {formatCurrency(calculatePricePerShare(transaction))}
                    </td>
                    <td className="transaction-trade-date-cell">
                      {formatDate(transaction.trade_date || transaction.tradeDate)}
                    </td>
                    <td className="transaction-settlement-date-cell">
                      {formatDate(transaction.settlement_date || transaction.settlementDate)}
                    </td>
                    <td className="transaction-broker-cell">
                      {transaction.broker_name || transaction.brokerName || '-'}
                    </td>
                    <td className="transaction-contract-cell">
                      {transaction.contract_number || transaction.contractNumber || '-'}
                    </td>
                    {activeTab !== 'sell' && (
                      <td className="transaction-money-gen-cell">
                        {formatCurrency(transaction.money_generation_cost || transaction.moneyGenerationCost)}
                      </td>
                    )}
                    {activeTab !== 'buy' && (
                      <td className="transaction-capital-gain-cell">
                        {formatCurrency(transaction.capital_gain || transaction.capitalGain)}
                      </td>
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Transaction Details Modal */}
      {isModalOpen && (
        <TransactionDetailsModal
          transaction={selectedTransaction}
          onClose={handleCloseModal}
          onSave={handleSave}
        />
      )}
    </div>
  );
};

export default TransactionView;
